package org.pms.silverocean.service.estateops;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.*;import java.util.List;import org.pms.silverocean.database.pms.entities.*;
public final class EstateOperationsModels{private EstateOperationsModels(){}public enum BudgetStatus{DRAFT,APPROVED,CLOSED}public enum MeetingStatus{SCHEDULED,HELD,CANCELLED}public enum ResolutionStatus{PROPOSED,PASSED,REJECTED,IMPLEMENTED}public enum WorkStatus{OPEN,ACKNOWLEDGED,IN_PROGRESS,COMPLETED,CANCELLED}
 public record BudgetCreate(long propertyId,@Min(2000)int budgetYear,@NotBlank @Size(max=120)String name,@NotBlank @Size(max=12)String currency){}public record BudgetLineCreate(@NotBlank @Size(max=80)String category,@Size(max=500)String description,@NotNull @PositiveOrZero BigDecimal plannedAmount){}public record Actual(@NotNull @PositiveOrZero BigDecimal actualAmount){}public record BudgetView(EstateBudget budget,List<EstateBudgetLine>lines,BigDecimal plannedTotal,BigDecimal actualTotal){}
 public record MeetingCreate(long propertyId,@NotBlank @Size(max=160)String title,@NotNull @Future ZonedDateTime scheduledAt,@Size(max=255)String venue,@PositiveOrZero int quorumRequired){}public record MeetingUpdate(@NotNull MeetingStatus status,@PositiveOrZero int attendeeCount,@Size(max=5000)String minutes){}
 public record ResolutionCreate(@NotBlank @Size(max=200)String title,@Size(max=3000)String decision,@FutureOrPresent LocalDate dueDate){}public record ResolutionUpdate(@NotNull ResolutionStatus status,@PositiveOrZero int votesFor,@PositiveOrZero int votesAgainst,@PositiveOrZero int votesAbstain,@Size(max=3000)String decision){}
 public record WorkCreate(long propertyId,@NotBlank @Size(max=120)String areaName,@NotBlank @Size(max=160)String title,@NotBlank @Size(max=2000)String description,@NotBlank @Size(max=50)String category,@NotBlank @Size(max=20)String priority,@Size(max=12)String currency){}public record WorkUpdate(@NotNull WorkStatus status,Long assignedProviderServiceId,ZonedDateTime scheduledAt,@PositiveOrZero BigDecimal estimatedCost,@PositiveOrZero BigDecimal actualCost,@Size(max=1000)String resolutionNotes){}
}
